    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.withdraw();
        uint beforeBal = address(this).balance;
        uint beforeContract = address(c).balance;
        c.fallback{value: amount}();
        uint recorded = c.balances(address(this));
        uint afterDeposit = address(c).balance;
        c.withdraw();
        uint afterWithdraw = address(c).balance;
        assert(recorded == amount && afterDeposit == beforeContract + amount && address(this).balance == beforeBal + amount && afterWithdraw == beforeContract && c.balances(address(this)) == 0);
    }
    receive() external payable {}
    fallback() external payable {}
}

